import { expect, test } from "./backend";

for (const colorScheme of ["light", "dark"] as const) {
  test(`${colorScheme} initial canvas and metadata work without JavaScript`, async ({
    browser,
    baseURL,
  }) => {
    const context = await browser.newContext({
      javaScriptEnabled: false,
      colorScheme,
    });
    const page = await context.newPage();
    await page.goto(`${baseURL}/`);
    const expected =
      colorScheme === "light" ? "rgb(233, 228, 237)" : "rgb(0, 0, 0)";
    await expect(page.locator("html")).toHaveCSS("background-color", expected);
    await expect(page.locator("html")).toHaveCSS("color-scheme", colorScheme);
    await expect(
      page.locator(
        `meta[name="theme-color"][media="(prefers-color-scheme: ${colorScheme})"]`,
      ),
    ).toHaveAttribute(
      "content",
      colorScheme === "light" ? "#e9e4ed" : "#000000",
    );
    let blockedStylesheets = 0;
    const initial = await context.newPage();
    await initial.route("**/*.css", (route) => {
      blockedStylesheets += 1;
      return route.abort();
    });
    await initial.goto(`${baseURL}/`);
    expect(blockedStylesheets).toBeGreaterThan(0);
    await expect(initial.locator("html")).toHaveCSS(
      "background-color",
      expected,
    );
    await expect(initial.locator("html")).toHaveCSS(
      "color-scheme",
      colorScheme,
    );
    await context.close();
  });
}
import { expect, test } from "./backend";
import type { Locator } from "@playwright/test";

test.use({ development: true });

async function contrast(
  locator: Locator,
  {
    foreground = "color",
    background = "self",
  }: {
    foreground?: "color" | "borderTopColor";
    background?: "self" | "page";
  } = {},
) {
  const colors = await locator.evaluate(
    (element, { foreground, background }) => ({
      foreground: getComputedStyle(element)[foreground],
      background: getComputedStyle(
        background === "page" ? document.documentElement : element,
      ).backgroundColor,
    }),
    { foreground, background },
  );
  function luminance(color: string) {
    const numbers = color.match(/[\d.]+/gu)?.map(Number) ?? [];
    const channels = color.startsWith("color(")
      ? numbers.map((n) => n * 255)
      : numbers;
    return channels.slice(0, 3).reduce((total, channel, index) => {
      const value = channel / 255;
      const linear =
        value <= 0.04045 ? value / 12.92 : ((value + 0.055) / 1.055) ** 2.4;
      return total + linear * [0.2126, 0.7152, 0.0722][index];
    }, 0);
  }
  const values = [luminance(colors.foreground), luminance(colors.background)];
  return (Math.max(...values) + 0.05) / (Math.min(...values) + 0.05);
}

