      });
      server.listen(0, "127.0.0.1");
      await once(server, "listening");
      const address = server.address();
      if (!address || typeof address === "string")
        throw new Error("No backend port");
      const port = 4300 + workerInfo.workerIndex;
      const child = spawn(
        process.execPath,
        development
